# **New Implementation**

We will re-implement the custom dataset class and model using the PyTorch Python API. We will also use the Hugging Face Transformers library to load the pre-trained BERT model and fine-tune it on our custom dataset.

```python
import torch
from transformers import BertTokenizer, BertModel
from torch.utils.data import Dataset, DataLoader
import pandas as pd

class CustomDataset(Dataset):
    def __init__(self, file_path, max_len):
        self.file_path = file_path
        self.max_len = max_len
        self.data = pd.read_csv(file_path, sep='\t', names=['review', 'label'])

    def __len__(self):
        return len(self.data)

    def __getitem__(self, idx):
        review = self.data.iloc[idx, 0]
        label = self.data.iloc[idx, 1]

        tokenizer = BertTokenizer.from_pretrained('bert-base-uncased')
        encoding = tokenizer.encode_plus(
            review,
            add_special_tokens=True,
            max_length=self.max_len,
            return_attention_mask=True,
            return_tensors='pt'
        )

        return {
            'input_ids': encoding['input_ids'].flatten(),
            'attention_mask': encoding['attention_mask'].flatten(),
            'label': torch.tensor(label, dtype=torch.long)
        }

# Load pre-trained BERT model and fine-tune it on our custom dataset
model = BertModel.from_pretrained('bert-base-uncased', num_labels=8)

# Create data loader
dataset = CustomDataset('path/to/data.txt', 512)
data_loader = DataLoader(dataset, batch_size=32, shuffle=True)

# Train model
device = torch.device('cuda' if torch.cuda.is_available() else 'cpu')
model.to(device)
criterion = torch.nn.CrossEntropyLoss()
optimizer = torch.optim.Adam(model.parameters(), lr=1e-5)

for epoch in range(3):
    model.train()
    total_loss = 0
    for batch in data_loader:
        input_ids = batch['input_ids'].to(device)
        attention_mask = batch['attention_mask'].to(device)
        labels = batch['label'].to(device)

        optimizer.zero_grad()

        outputs = model(input_ids, attention_mask=attention_mask, labels=labels)
        loss = criterion(outputs, labels)

        loss.backward()
        optimizer.step()

        total_loss += loss.item()
    print(f'Epoch {epoch+1}, Loss: {total_loss / len(data_loader)}')

# Save model
torch.save(model.state_dict(), 'path/to/model.pth')
```

