```typescript
import { Directive, ElementRef } from '@angular/core';
import { DragDrop } from '@angular/cdk/drag-drop';
import { CdkDrag } from '@angular/cdk/drag-drop';

@Directive({
  selector: '[draggable]'
})
export class DraggableDirective {
  constructor(private dragDrop: DragDrop, private elementRef: ElementRef) {
    const dragContainer = this.dragDrop.createDrag(this.elementRef.nativeElement);
    dragContainer.withHandle(this.elementRef.nativeElement.querySelector('.drag-handle'));
  }

  @Input() dragHandle: string;
  @Input() dropZone: string;

  ngAfterViewInit() {
    this.dragDrop.connect(this.elementRef.nativeElement, this.dropZone);
  }

  ngOnDestroy() {
    this.dragDrop.disconnect(this.elementRef.nativeElement);
  }
}
```

