function azure_sql_query($server, $database, $username, $password, $query) {
    // Define the ODBC driver to use ( equivalent to '{ODBC Driver 17 for SQL Server}' in Python )
    $driver = 'ODBC Driver 17 for SQL Server';

    // Construct the connection string ( equivalent to the Python connection_string )
