        // If not, throw an exception with the error message
        throw new Exception(odbc_errormsg());
    }

    // Prepare the query for execution
    $result = odbc_prepare($connection, $query);

    // Execute the query
    odbc_execute($result);

    // Check if the query is a SELECT statement
    if (strtoupper(trim($query)) === 'SELECT') {
