The final response is the implemented code, which includes the functions for each supported operation type and the main function that applies the operations sequentially to the input image.

Here is the final code:
```python
import numpy as np

def normalize_image(image, mean, std):
    # Normalize the image using mean and standard deviation
    if not isinstance(image, np.ndarray):
        raise ValueError("Input image must be a numpy array")
    if not isinstance(mean, (list, np.ndarray)) or not isinstance(std, (list, np.ndarray)):
        raise ValueError("Mean and standard deviation must be lists or numpy arrays")
    image = image.astype(np.float32)
    image -= np.array(mean, dtype=np.float32)
    image /= np.array(std, dtype=np.float32)
    return image

def format_shape_image(image, input_format):
    # Reshape the image according to the specified format
    if not isinstance(image, np.ndarray):
        raise ValueError("Input image must be a numpy array")
    if input_format not in ['NCHW', 'NHWC']:
        raise ValueError(f"Unsupported format: {input_format}")
    if input_format == 'NCHW':
        image = image.transpose((0, 3, 1, 2))
    elif input_format == 'NHWC':
        image = image.transpose((0, 2, 3, 1))
    return image

def collect_image_data(image_data, keys):
    # Collect specific keys from the image data
    if not isinstance(image_data, dict):
        raise ValueError("Input image data must be a dictionary")
    collected_data = {}
    for key in keys:
        if key in image_data:
            collected_data[key] = image_data[key]
    return collected_data

def apply_image_operations(operations, input_image):
    # Apply a series of image operations to the input image
    if not isinstance(operations, list):
        raise ValueError("Input operations must be a list")
    if not isinstance(input_image, np.ndarray):
        raise ValueError("Input image must be a numpy array")
    image_data = {'image': input_image}
    for operation in operations:
        op_type = operation['type']
        if op_type == 'Normalize':
            image_data['image'] = normalize_image(image_data['image'], operation['mean'], operation['std'])
        elif op_type == 'FormatShape':
            image_data['image'] = format_shape_image(image_data['image'], operation['input_format'])
        elif op_type == 'Collect':
            image_data = collect_image_data(image_data, operation['keys'])
        else:
            raise ValueError(f"Unsupported operation type: {op_type}")
    return image_data['image']
```
This code can be used to apply a series of image operations to an input image, where the operations are represented as a list of dictionaries.

